evaluation.reference:
Interfaz Shape
  Metodo Area() Como Real;
FinInterfaz

Clase Rectangle Realiza Shape
  Definir rectLength, width Como Real;
  Metodo Constructor(newLength Como Real, newWidth Como Real)
    Este.rectLength <- newLength;
    Este.width <- newWidth;
  FinMetodo
  Metodo Area() Como Real
    Retornar Este.rectLength * Este.width;
  FinMetodo
FinClase

Clase Square Realiza Shape
  Definir side Como Real;
  Metodo Constructor(newSide Como Real)
    Este.side <- newSide;
  FinMetodo
  Metodo Area() Como Real
    Retornar Este.side * Este.side;
  FinMetodo
FinClase

Clase Triangle Realiza Shape
  Definir base, height Como Real;
  Metodo Constructor(newBase Como Real, newHeight Como Real)
    Este.base <- newBase;
    Este.height <- newHeight;
  FinMetodo
  Metodo Area() Como Real
    Retornar Este.base * Este.height / 2;
  FinMetodo
FinClase

SubProceso AreaOf<T: Shape>(shape Como T) Como Real
  Retornar shape.Area();
FinSubProceso

Algoritmo Shapes
  Definir shapeKind Como Cadena;
  Definir sizeOne, sizeTwo Como Real;
  Leer shapeKind;
  Si shapeKind = "square" Entonces
    Leer sizeOne;
    Escribir AreaOf(Nuevo Square(sizeOne));
  Sino
    Leer sizeOne;
    Leer sizeTwo;
    Si shapeKind = "rectangle" Entonces
      Escribir AreaOf(Nuevo Rectangle(sizeOne, sizeTwo));
    Sino
      Escribir AreaOf(Nuevo Triangle(sizeOne, sizeTwo));
    FinSi
  FinSi
FinAlgoritmo
